                return remaining.length() > 0 ? remaining : "";
            }
        } else if (path.length() > 1 && path.charAt(1) == sep) {
            // UNC path
            int nextsep = path.indexOf(sep, 2);
            nextsep = path.indexOf(sep, nextsep + 1);
            String urn = (nextsep > 2) ? path.substring(0, nextsep + 1) : path;
            return path.substring(urn.length());
        } else {
            // Driveless absolute path (e.g., Unix `/home/user`)
            return path.substring(1);
        }

        // Fallback: use the root length directly
        return path.substring(root.length());
    }

 * @throws java.lang.NullPointerException if path is null.
 * @since Ant 1.7
 */
public String[] dissect(String path) {
    char sep = File.separatorChar;
    path = path.replace('/', sep).replace('\\', sep);

    // make sure we are dealing with an absolute path
    if (!isAbsolutePath(path)) {
        throw new BuildException(path + " is not an absolute path");
    }
    String root = extractRoot(path, sep);
    String remainingPath = extractRemainingPath(path, root, sep);
    return new String[] {root, remainingPath};
}

/**
 * Extracts the root portion of an absolute path.
 * @param path the absolute path.
 * @param sep the file separator character.
 * @return the root string.
 */
private String extractRoot(String path, char sep) {
    int colon = path.indexOf(':');
    if (colon > 0 && (ON_DOS || ON_NETWARE)) {
        return extractDosOrNetwareRoot(path, colon, sep);
    } else if (path.length() > 1 && path.charAt(1) == sep) {
        return extractUncRoot(path, sep);
    } else {
        return File.separator;
    }
}

/**
 * Extracts the root for DOS/NetWare-style paths (e.g., C:\...).
 * @param path the absolute path.
 * @param colon the index of the colon in the drive spec.
 * @param sep the file separator character.
 * @return the root string.
 */
private String extractDosOrNetwareRoot(String path, int colon, char sep) {
    int next = colon + 1;
    String root = path.substring(0, next) + sep;
    int start = (path.charAt(next) == sep) ? next + 1 : next;
    StringBuilder sb = new StringBuilder();
    for (int i = start; i < path.length(); i++) {
        if (path.charAt(i) != sep || (i > 0 && path.charAt(i - 1) != sep)) {
            sb.append(path.charAt(i));
        }
    }
    // remaining path is the normalized part after root
    return sb.toString();
}

/**
 * Extracts the root for UNC paths (e.g., \\server\share\...).
 * @param path the absolute path.
 * @param sep the file separator character.
 * @return the root string.
 */
private String extractUncRoot(String path, char sep) {
    int nextsep = path.indexOf(sep, 2);
    nextsep = path.indexOf(sep, nextsep + 1);
    String root = (nextsep > 2) ? path.substring(0, nextsep + 1) : path;
    return root;
}

/**
 * Extracts the remaining path after the root.
 * @param path the absolute path.
 * @param root the extracted root.
 * @param sep the file separator character.
 * @return the remaining path string.
 */
private String extractRemainingPath(String path, String root, char sep) {
    if (path.length() > 1 && path.charAt(1) == sep) {
        // UNC path
        int nextsep = path.indexOf(sep, 2);
        nextsep = path.indexOf(sep, nextsep + 1);
        String rootCandidate = (nextsep > 2) ? path.substring(0, nextsep + 1) : path;
        return path.substring(rootCandidate.length());
    } else if (path.indexOf(':') > 0 && (ON_DOS || ON_NETWARE)) {
        // DOS/NetWare path
        int colon = path.indexOf(':');
        int next = colon + 1;
        int start = (path.charAt(next) == sep) ? next + 1 : next;
        StringBuilder sb = new StringBuilder();
        for (int i = start; i < path.length(); i++) {
            if (path.charAt(i) != sep || (i > 0 && path.charAt(i - 1) != sep)) {
                sb.append(path.charAt(i));
            }
        }
        return sb.toString();
    } else {
        return path.substring(1);
    }
