private int tryProcessWithArgumentProcessors(String[] args, int i, ProcessingState state,
                                              ArgumentProcessorRegistry processorRegistry) {
    for (ArgumentProcessor processor : processorRegistry.getProcessors()) {
        int newI = processor.readArguments(args, i);
        if (newI != -1) {
            List<String> extraArgs = state.extraArguments.computeIfAbsent(processor.getClass(),
                    k -> new ArrayList<>());
            for (; i <= newI && i < args.length; i++) {
                extraArgs.add(args[i]);
            }
            return i;
        }
    }

    String msg = "Unknown argument: " + args[i];
    System.err.println(msg);
    printUsage();
    throw new BuildException("");
}

/**
 * Handles -logfile/-l argument.
 */
private int handleLogfileArg(String[] args, int i, ProcessingState state) {
    try {
        File logFile = new File(args[++i]);
        PrintStream logTo = new PrintStream(new FileOutputStream(logFile));
        state.logTo = logTo;
        isLogFileUsed = true;
    } catch (IOException ioe) {
        String msg = "Cannot write on the specified log file. "
            + "Make sure the path exists and you have write permissions.";
        throw new BuildException(msg);
    } catch (ArrayIndexOutOfBoundsException aioobe) {
        String msg = "You must specify a log file when "
            + "using the -log argument";
        throw new BuildException(msg);
    }
    return i;
}

/**
 * Handles -find/-s argument.
 */
private int handleFindArg(String[] args, int i, ProcessingState state) {
    state.searchForFile = true;
    if (i < args.length - 1) {
        state.searchForThis = args[++i];
    }
    return i;
}

/**
 * Processes flags related to usage/version/diagnostics.
 */
private void handleUsageOrVersionFlag(String arg, ProcessingState state) {
    if ("-help".equals(arg) || "-h".equals(arg)) {
        state.justPrintUsage = true;
    } else if ("-version".equals(arg)) {
        state.justPrintVersion = true;
    } else if ("-diagnostics".equals(arg)) {
        state.justPrintDiagnostics = true;
    }
}

/**
 * Handles post-processing logic based on collected flags.
 */
private void handlePostProcessing(ProcessingState state) {
    if (state.msgOutputLevel >= Project.MSG_VERBOSE || state.justPrintVersion) {
        printVersion(state.msgOutputLevel);
    }

    if (state.justPrintUsage || state.justPrintVersion || state.justPrintDiagnostics) {
        if (state.justPrintUsage) {
            printUsage();
        }
        if (state.justPrintDiagnostics) {
            Diagnostics.doReport(System.out, state.msgOutputLevel);
        }
    }
}

/**
 * Post-processes build file path after parsing arguments.
 */
private void postProcessBuildFile(ProcessingState state) {
    if (buildFile == null) {
        handleMissingBuildFile(state);
    }

    if (!buildFile.exists()) {
        System.out.println("Buildfile: " + buildFile + " does not exist!");
        throw new BuildException("Build failed");
    }

    if (buildFile.isDirectory()) {
        File whatYouMeant = new File(buildFile, "build.xml");
        if (whatYouMeant.isFile()) {
            buildFile = whatYouMeant;
        } else {
            System.out.println("What? Buildfile: " + buildFile + " is a dir!");
            throw new BuildException("Build failed");
        }
    }

    buildFile = FileUtils.getFileUtils().normalize(buildFile.getAbsolutePath());
}

/**
 * Handles logic when no build file is specified.
 */
private void handleMissingBuildFile(ProcessingState state) {
    if (state.searchForFile) {
        if (state.searchForThis != null) {
            buildFile = findBuildFile(System.getProperty("user.dir"), state.searchForThis);
            if (buildFile == null) {
                throw new BuildException("Could not locate a build file!");
            }
        } else {
            searchDefaultBuildFile();
        }
    } else {
        searchDefaultBuildFile();
    }
}

/**
 * Searches for default build files using project helpers.
 */
private void searchDefaultBuildFile() {
    Iterator<ProjectHelper> it = ProjectHelperRepository.getInstance().getHelpers();
    do {
        ProjectHelper helper = it.next();
        String defaultBuildFile = helper.getDefaultBuildFile();
        if (msgOutputLevel >= Project.MSG_VERBOSE) {
            System.out.println("Trying the default build file: " + defaultBuildFile);
        }
        buildFile = new File(defaultBuildFile);
    } while (!buildFile.exists() && it.hasNext());

    if (buildFile == null || !buildFile.exists()) {
        throw new BuildException("Could not locate a build file!");
    }
}

/**
 * Redirects output streams if logging to a file.
 */
private void redirectOutputIfNeeded(ProcessingState state) {
    if (state.logTo != null) {
        out = state.logTo;
        err = state.logTo;
        System.setOut(out);
        System.setErr(err);
    }
}

/**
 * Throws a BuildException for invalid launcher commands.
 */
private void throwInvalidLaunchCommand(String arg) {
    String msg = "Ant's Main method is being handed "
            + "an option " + arg + " that is only for the launcher class."
            + "\nThis can be caused by a version mismatch between "
            + "the ant script/.bat file and Ant itself.";
    throw new BuildException(msg);
}

/**
 * Holds intermediate processing state during argument parsing.
 */
private static class ProcessingState {
    final String[] args;
    final ArgumentProcessorRegistry processorRegistry;
    String searchForThis = null;
    boolean searchForFile = false;
    PrintStream logTo = null;
    boolean justPrintUsage = false;
    boolean justPrintVersion = false;
    boolean justPrintDiagnostics = false;
    boolean silent = false;
    boolean allowInput = true;
    int msgOutputLevel = Project.MSG_INFO;
    boolean emacsMode = false;
    boolean projectHelp = false;
    boolean keepGoingMode = false;
    boolean proxy = false;
    Map<Class<?>, List<String>> extraArguments = new HashMap<>();

    ProcessingState(String[] args, ArgumentProcessorRegistry processorRegistry) {
        this.args = args;
        this.processorRegistry = processorRegistry;
    }
}

