/**
 * Handles the -logfile/-l argument and creates the log stream.
 * @param logFilePath the path to the log file
 * @return the created PrintStream
 */
private PrintStream createLogStream(String logFilePath) {
    try {
        File logFile = new File(logFilePath);
        return new PrintStream(new FileOutputStream(logFile));
    } catch (IOException ioe) {
        String msg = "Cannot write on the specified log file. "
            + "Make sure the path exists and you have write "
            + "permissions.";
        throw new BuildException(msg);
    }
}

/**
 * Processes a custom argument using registered argument processors.
 * @param args the command line arguments
 * @param i the current index in args
 * @param processorRegistry the registry of argument processors
 * @return the updated index
 */
private int processCustomArgument(String[] args, int i, ArgumentProcessorRegistry processorRegistry) {
    boolean processed = false;
    for (ArgumentProcessor processor : processorRegistry.getProcessors()) {
        int newI = processor.readArguments(args, i);
        if (newI != -1) {
            List<String> extraArgs = extraArguments.get(processor.getClass());
            if (extraArgs == null) {
                extraArgs = new ArrayList<String>();
                extraArguments.put(processor.getClass(), extraArgs);
            }
            for (; i < newI && i < args.length; i++) {
                extraArgs.add(args[i]);
            }
            processed = true;
            break;
        }
    }
    if (!processed) {
        // we don't have any more args to recognize!
        String msg = "Unknown argument: " + args[i];
        System.err.println(msg);
        printUsage();
        throw new BuildException("");
    }
    return i;
}

/**
 * Handles searching for a build file when -find/-s is used.
 * @param args the command line arguments
 * @param searchForThis the optional search file name
 */
private void handleSearchForBuildFile(String[] args, String searchForThis) {
    if (searchForThis != null) {
        buildFile = findBuildFile(System.getProperty("user.dir"), searchForThis);
        if (buildFile == null) {
            throw new BuildException("Could not locate a build file!");
        }
    } else {
        // no search file specified: so search an existing default file
        Iterator<ProjectHelper> it = ProjectHelperRepository.getInstance().getHelpers();
        do {
            ProjectHelper helper = it.next();
            searchForThis = helper.getDefaultBuildFile();
            if (msgOutputLevel >= Project.MSG_VERBOSE) {
                System.out.println("Searching the default build file: " + searchForThis);
            }
            buildFile = findBuildFile(System.getProperty("user.dir"), searchForThis);
        } while (buildFile == null && it.hasNext());
        if (buildFile == null) {
            throw new BuildException("Could not locate a build file!");
        }
    }
}

/**
 * Handles default build file search when no build file is specified.
 */
private void handleDefaultBuildFileSearch() {
    Iterator<ProjectHelper> it = ProjectHelperRepository.getInstance().getHelpers();
    do {
        ProjectHelper helper = it.next();
        buildFile = new File(helper.getDefaultBuildFile());
        if (msgOutputLevel >= Project.MSG_VERBOSE) {
            System.out.println("Trying the default build file: " + buildFile);
        }
    } while (!buildFile.exists() && it.hasNext());
}

/**
 * Validates the build file exists and is not a directory.
 * @return the updated index (always 0, used for consistency)
 */
private int validateBuildFile() {
    // make sure buildfile exists
    if (!buildFile.exists()) {
        System.out.println("Buildfile: " + buildFile + " does not exist!");
        throw new BuildException("Build failed");
    }

    if (buildFile.isDirectory()) {
        File whatYouMeant = new File(buildFile, "build.xml");
        if (whatYouMeant.isFile()) {
            buildFile = whatYouMeant;
        } else {
            System.out.println("What? Buildfile: " + buildFile + " is a dir!");
            throw new BuildException("Build failed");
        }
    }
    return 0;
}

