 * @param end      the association end role to inspect
 * @param originalRole the original classifier role (to exclude from results)
 * @param roles    the list to which classifier roles are added
 */
private void expandClassifierRolesFromAssociationEnd(
        AssociationEnd end, ClassifierRole originalRole, List<Classifier> roles) {
    UmlAssociation assoc = end.getAssociation();
    for (AssociationEnd end2 : assoc.getConnection()) {
        Classifier classifier = end2.getParticipant();
        if (classifier != originalRole && classifier instanceof ClassifierRole) {
            roles.add(classifier);
        }
    }
