            for (AssociationEnd end : associationEnds) {
                processAssociationEnd(end, role, roles);
            }
        }
    } catch (InvalidObjectException e) {
        throw new InvalidElementException(e);
    }
    return roles;
}

/**
 * Processes a single association end to extract related classifier roles.
 *
 * @param end the association end to process
 * @param role the original classifier role
 * @param roles the list to which matching classifier roles are added
 */
private void processAssociationEnd(AssociationEnd end, ClassifierRole role,
                                   List<Classifier> roles) {
    if (!(end instanceof AssociationEndRole)) {
        return;
    }
    UmlAssociation assoc = end.getAssociation();
    for (AssociationEnd end2 : assoc.getConnection()) {
        Classifier classifier = end2.getParticipant();
        if (classifier != role && classifier instanceof ClassifierRole) {
            roles.add(classifier);
        }
    }
}

