public Object findOperationByName(Object trans, String opname) {
    if (!(trans instanceof Transition)) {
        throw new IllegalArgumentException();
    }
    try {
        Object sm = getStateMachine(trans);
        if (sm == null) {
            return null;
        }
        Object context = Model.getFacade().getContext(sm);
        if (context == null) {
            return null;
        }
        Object classifier = getClassifierForContext(context);
        if (classifier != null) {
            Feature found = findOperationInClassifier((Classifier) classifier, opname);
            if (found != null) {
                return found;
            }
        }
        Namespace pack = getSearchNamespace(context, (Classifier) classifier);
        if (pack != null) {
            return findOperationInNamespace(pack, opname);
        }
    } catch (InvalidObjectException e) {
        throw new InvalidElementException(e);
    }
    return null;
}

/**
 * Determines the appropriate Classifier to search for operations based on the context.
 * @param context The context object (may be Classifier or BehavioralFeature)
 * @return Classifier or null
 */
private Object getClassifierForContext(Object context) {
    if (context instanceof Classifier) {
        return context;
    }
    if (context instanceof BehavioralFeature) {
        return ((BehavioralFeature) context).getOwner();
    }
    return null;
}

/**
 * Searches for an operation with the specified name within a given Classifier.
 * @param classifier The Classifier to search
 * @param opname The operation name to match
 * @return Feature (Operation) if found, null otherwise
 */
private Feature findOperationInClassifier(Classifier classifier, String opname) {
    for (Feature f : classifier.getFeature()) {
        if (f instanceof Operation && opname.equals(f.getName())) {
            return f;
        }
    }
    return null;
}

/**
 * Determines the Namespace in which to search for operations when no match is found in the primary Classifier.
 * @param context The context object
 * @param classifier The primary classifier (may be null)
 * @return Namespace to search, or null if none applicable
 */
private Namespace getSearchNamespace(Object context, Classifier classifier) {
    if (context instanceof UmlPackage) {
        return (Namespace) context;
    }
    if (classifier != null) {
        return findTopLevelNamespace(classifier.getNamespace());
    }
    return null;
}

/**
 * Traverses the namespace hierarchy to find the top-level Namespace.
 * @param namespace Start namespace
 * @return Top-level Namespace or null
 */
private Namespace findTopLevelNamespace(Namespace namespace) {
    Namespace parent = namespace;
    while (parent != null && parent.getNamespace() != null
            && parent.getNamespace() instanceof Classifier) {
        parent = parent.getNamespace();
    }
    return parent;
}

/**
 * Searches for an operation with the specified name within owned Elements of the given Namespace.
 * @param pack The Namespace to search
 * @param opname The operation name to match
 * @return Feature (Operation) if found, null otherwise
 */
private Feature findOperationInNamespace(Namespace pack, String opname) {
    for (ModelElement me : pack.getOwnedElement()) {
        if (me instanceof Classifier) {
            Classifier classifier2 = (Classifier) me;
            Feature found = findOperationInClassifier(classifier2, opname);
            if (found != null) {
                return found;
            }
        }
    }
    return null;
}

public Object findOperationByName(Object trans, String opname) {
    if (!(trans instanceof Transition)) {
        throw new IllegalArgumentException();
    }

    try {
        Object sm = getStateMachine(trans);
        Object context = Model.getFacade().getContext(sm);
        Classifier classifier = extractClassifier(context);
        if (classifier != null) {
            Object found = findOperationInClassifier(classifier, opname);
            if (found != null) {
                return found;
            }
        }

        Namespace pack = extractNamespace(context, classifier);
        if (pack != null) {
            Object found = findOperationInNamespace(pack, opname);
            if (found != null) {
                return found;
            }
        }
    } catch (InvalidObjectException e) {
        throw new InvalidElementException(e);
    }

    return null;
}

private Classifier extractClassifier(Object context) {
    if (context instanceof Classifier) {
        return (Classifier) context;
    }
    if (context instanceof BehavioralFeature) {
        return ((BehavioralFeature) context).getOwner();
    }
    return null;
}

private Object findOperationInClassifier(Classifier classifier, String opname) {
    for (Feature f : classifier.getFeature()) {
        if (f instanceof Operation && opname.equals(f.getName())) {
            return f;
        }
    }
    return null;
}

private Namespace extractNamespace(Object context, Classifier classifier) {
    if (context instanceof UmlPackage) {
        return (Namespace) context;
    }
    if (classifier == null) {
        return null;
    }
    return findRootNamespace(classifier.getNamespace());
}

private Namespace findRootNamespace(Namespace ns) {
    Namespace parent = ns;
    while (parent instanceof Classifier && parent.getNamespace() != null) {
        parent = parent.getNamespace();
    }
    return parent instanceof Namespace ? parent : null;
}

private Object findOperationInNamespace(Namespace pack, String opname) {
    for (ModelElement me : pack.getOwnedElement()) {
        if (me instanceof Classifier) {
            Object found = findOperationInClassifier((Classifier) me, opname);
            if (found != null) {
                return found;
            }
        }
    }
    return null;
}

