public Object findOperationByName(Object trans, String opname) {
    if (!(trans instanceof Transition)) {
        throw new IllegalArgumentException();
    }
    try {
        Object sm = getStateMachine(trans);
        Object context = Model.getFacade().getContext(sm);
        Classifier classifier = getClassifierFromContext(context);
        Operation found = findOperationInClassifier(classifier, opname);
        if (found != null) {
            return found;
        }
        Namespace pack = getSearchNamespace(context, classifier);
        return findOperationInNamespace(pack, opname);
    } catch (InvalidObjectException e) {
        throw new InvalidElementException(e);
    }
}

/**
 * Extracts a Classifier from the given context, if possible.
 *
 * @param context The UML context object
 * @return The resolved Classifier, or null if none found
 */
private Classifier getClassifierFromContext(Object context) {
    if (context instanceof Classifier) {
        return (Classifier) context;
    }
    if (context instanceof BehavioralFeature) {
        return ((BehavioralFeature) context).getOwner();
    }
    return null;
}

/**
 * Searches for an Operation with the given name in the passed Classifier.
 *
 * @param classifier The Classifier to search
 * @param opname The operation name to find
 * @return The matching Operation, or null if not found
 */
private Operation findOperationInClassifier(Classifier classifier, String opname) {
    if (classifier == null) {
        return null;
    }
    for (Feature f : classifier.getFeature()) {
        if (f instanceof Operation && opname.equals(f.getName())) {
            return (Operation) f;
        }
    }
    return null;
}

/**
 * Determines the root Namespace to search for operations when none are found
 * in the direct context.
 *
 * @param context The current context
 * @param classifier The resolved classifier, if any
 * @return The Namespace to search, or null if none
 */
private Namespace getSearchNamespace(Object context, Classifier classifier) {
    if (context instanceof UmlPackage) {
        return (Namespace) context;
    }
    if (classifier != null) {
        Namespace parent = classifier.getNamespace();
        while (parent instanceof Classifier) {
            if (parent.getNamespace() == null) {
                break;
            }
            parent = parent.getNamespace();
        }
        return parent != null ? parent : null;
    }
    return null;
}

/**
 * Searches for an Operation with the given name within the Namespace and
 * its contained Classifiers.
 *
 * @param namespace The Namespace to search
 * @param opname The operation name to find
 * @return The matching Operation, or null if not found
 */
private Operation findOperationInNamespace(Namespace namespace, String opname) {
    if (namespace == null) {
        return null;
    }
    for (ModelElement me : namespace.getOwnedElement()) {
        if (me instanceof Classifier) {
            Classifier classifier2 = (Classifier) me;
            for (Feature f : classifier2.getFeature()) {
                if (f instanceof Operation && opname.equals(f.getName())) {
                    return (Operation) f;
                }
            }
        }
    }
    return null;
}

