        for match in _archive_re.finditer(el.get('archive')):
            value = match.group(0)
            if codebase is not None:
                value = urljoin(codebase, value)
            yield (el, 'archive', value, match.start())


def _iter_standard_links(el, attribs):
    """Iterate over standard link attributes on an element."""
    for attr in attribs:
        if attr in _link_attrs:
            yield (el, attr, attribs[attr], 0)


def _iter_css_links(el, attribs, find_links_in_css):
    """Iterate over CSS-based links (in <style> tags or style attributes)."""
    if not find_links_in_css:
        return
    tag = barename(el.tag).lower()
    if tag == 'style' and el.text:
        for match in _css_url_re.finditer(el.text):
            yield (el, None, match.group(1), match.start(1))
        for match in _css_import_re.finditer(el.text):
            yield (el, None, match.group(1), match.start(1))
    if 'style' in attribs:
        for match in _css_url_re.finditer(attribs['style']):
            yield (el, 'style', match.group(1), match.start(1))


