def _build_media(base, definition):
    """
    Build and return a Media object combining base media with a class's Media definition.
    Handles the 'extend' attribute to optionally merge or replace base media.
    """
    extend = getattr(definition, 'extend', True)
    if not extend:
        return Media(definition)

    if extend is True:
        return base + Media(definition)

    # extend is a sequence of media types to include from base
    combined = Media()
    for medium in extend:
        combined += base[medium]
    return combined + Media(definition)


