def _iterlinks_for_object(el, codebase, find_links_in_css):
    """Iterator over link elements inside an <object> tag."""
    if codebase is not None:
        yield (el, 'codebase', codebase, 0)
    for attrib in ('classid', 'data'):
        if attrib in el.attrib:
