def _iterlinks_for_css(el, root_tag):
    """Iterator over links found in CSS style rules."""
    if root_tag == 'style' and el.text:
        for match in _css_url_re.finditer(el.text):
            yield (el, None, match.group(1), match.start(1))
        for match in _css_import_re.finditer(el.text):
            yield (el, None, match.group(1), match.start(1))
    if 'style' in el.attrib:
        for match in _css_url_re.finditer(el.attrib['style']):
            yield (el, 'style', match.group(1), match.start(1))


def iterlinks(root, find_links_in_css=True):
    '''
    Iterate over all links in a OEB Document.


    :param root: A valid lxml.etree element.
    '''
    assert etree.iselement(root)

    for el in root.iter():
        attribs = el.attrib
        try:
            tag = barename(el.tag).lower()
        except Exception:
            continue

        if tag == 'object':
            codebase = el.get('codebase') if 'codebase' in attribs else None
            for result in _iterlinks_for_object(el, codebase, find_links_in_css):
                yield result
        else:
            for result in _iterlinks_for_attr(el, find_links_in_css):
                yield result

        if not find_links_in_css:
            continue
        for result in _iterlinks_for_css(el, tag):
            yield result


