def _group_objects(self, obj_list, context):
    """
    Group objects by evaluating the expression on each object.
    """
    def get_grouper(obj):
        context.push()
        try:
            context[self.var_name] = obj
            return self.expression.resolve(context, True)
        finally:
            context.pop()

