private synchronized void setupConnection() throws IOException {
      short ioFailures = 0;
      short timeoutFailures = 0;
      while (true) {
        try {
          this.socket = createAndConfigureSocket();
          bindSocketIfKerberos();
          NetUtils.connect(this.socket, server, connectionTimeout);
          adjustTimeoutAndPingInterval();
          return;
        } catch (ConnectTimeoutException toe) {
          handleConnectTimeout(timeoutFailures++, toe);
          timeoutFailures = updateAddressAndResetFailures(timeoutFailures, ioFailures);
        } catch (IOException ie) {
          handleIOException(ie);
          ioFailures = updateAddressAndResetFailures(ioFailures, timeoutFailures);
        }
      }
    }

    private Socket createAndConfigureSocket() throws IOException {
      Socket socket = socketFactory.createSocket();
      socket.setTcpNoDelay(tcpNoDelay);
      socket.setKeepAlive(true);
      return socket;
    }

    private void bindSocketIfKerberos() {
      UserGroupInformation ticket = remoteId.getTicket();
      if (ticket == null || !ticket.hasKerberosCredentials()) {
        return;
      }

      KerberosInfo krbInfo = remoteId.getProtocol()
          .getAnnotation(KerberosInfo.class);
      if (krbInfo == null || krbInfo.clientPrincipal() == null) {
        return;
      }

      String host = SecurityUtil.getHostFromPrincipal(
          remoteId.getTicket().getUserName());
      InetAddress localAddr = NetUtils.getLocalInetAddress(host);
      if (localAddr != null) {
        this.socket.bind(new InetSocketAddress(localAddr, 0));
      }
    }

    private void adjustTimeoutAndPingInterval() {
      if (rpcTimeout > 0) {
        pingInterval = rpcTimeout;  // rpcTimeout overwrites pingInterval
      }
      this.socket.setSoTimeout(pingInterval);
    }

    private void handleConnectTimeout(int numRetries, IOException exception) throws IOException {
      closeConnection();
      if (numRetries >= maxRetriesOnSocketTimeouts) {
        throw exception;
      }
      LOG.info("Retrying connect to server: " + server + ". Already tried "
          + numRetries + " time(s); maxRetries=" + maxRetriesOnSocketTimeouts);
    }

    private void handleIOException(IOException exception) throws IOException {
      if (connectionRetryPolicy.shouldRetry(exception, 0, 0, true)
          .action == RetryAction.RetryDecision.FAIL) {
        throw exception;
      }
      closeConnection();
    }

    private short updateAddressAndResetFailures(short failures1, short failures2) {
      if (updateAddress()) {
        return 0;
      }
      return (short)(failures1 + 1);
    }

private synchronized void setupConnection() throws IOException {
  short ioFailures = 0;
  short timeoutFailures = 0;
  while (true) {
    try {
      establishSocketConnection();
      configureSocketTimeouts();
      return;
    } catch (ConnectTimeoutException toe) {
      handleTimeoutFailure(toe, timeoutFailures++, maxRetriesOnSocketTimeouts);
    } catch (IOException ie) {
      handleIoFailure(ie, ioFailures++);
