private void establishSocketConnection() throws IOException {
  this.socket = socketFactory.createSocket();
  this.socket.setTcpNoDelay(tcpNoDelay);
  this.socket.setKeepAlive(true);

  bindSocketToPrincipalAddress();

  NetUtils.connect(this.socket, server, connectionTimeout);
}

private void bindSocketToPrincipalAddress() throws IOException {
  UserGroupInformation ticket = remoteId.getTicket();
  if (ticket == null || !ticket.hasKerberosCredentials()) {
    return;
  }

  KerberosInfo krbInfo = remoteId.getProtocol().getAnnotation(KerberosInfo.class);
  if (krbInfo == null || krbInfo.clientPrincipal() == null) {
    return;
  }

  String host = SecurityUtil.getHostFromPrincipal(remoteId.getTicket().getUserName());
  InetAddress localAddr = NetUtils.getLocalInetAddress(host);
  if (localAddr != null) {
    this.socket.bind(new InetSocketAddress(localAddr, 0));
  }
}

private void configureSocketTimeouts() {
  if (rpcTimeout > 0) {
    pingInterval = rpcTimeout;  // rpcTimeout overwrites pingInterval
  }
  this.socket.setSoTimeout(pingInterval);
}

private void handleTimeoutFailure(ConnectTimeoutException toe, short currentRetries, int maxRetries) throws IOException {
  if (updateAddress()) {
    timeoutFailures = ioFailures = 0;
  }
  handleConnectionTimeout(currentRetries, maxRetries, toe);
}

private void handleIoFailure(IOException ie, short currentRetries) throws IOException {
  if (updateAddress()) {
    timeoutFailures = ioFailures = 0;
  }
  handleConnectionFailure(currentRetries, ie);
}

private synchronized void setupConnection() throws IOException {
      short ioFailures = 0;
      short timeoutFailures = 0;
      while (true) {
        try {
          this.socket = socketFactory.createSocket();
          this.socket.setTcpNoDelay(tcpNoDelay);
          this.socket.setKeepAlive(true);

          UserGroupInformation ticket = remoteId.getTicket();
          if (ticket != null && ticket.hasKerberosCredentials()) {
            setupSocketBindingForKerberos(ticket);
          }

          NetUtils.connect(this.socket, server, connectionTimeout);
          if (rpcTimeout > 0) {
            pingInterval = rpcTimeout;
          }
          this.socket.setSoTimeout(pingInterval);
          return;
        } catch (ConnectTimeoutException toe) {
          handleRetryWithAddressUpdate(timeoutFailures++, maxRetriesOnSocketTimeouts, toe);
        } catch (IOException ie) {
          handleRetryWithAddressUpdate(ioFailures++, -1, ie);
        }
      }
    }

    private void setupSocketBindingForKerberos(UserGroupInformation ticket) throws IOException {
      KerberosInfo krbInfo = remoteId.getProtocol().getAnnotation(KerberosInfo.class);
      if (krbInfo == null || krbInfo.clientPrincipal() == null) {
        return;
      }
      String host = SecurityUtil.getHostFromPrincipal(ticket.getUserName());
      InetAddress localAddr = NetUtils.getLocalInetAddress(host);
      if (localAddr != null) {
        this.socket.bind(new InetSocketAddress(localAddr, 0));
      }
    }

    private void handleRetryWithAddressUpdate(int currentFailures, int maxRetries, IOException exception) throws IOException {
      if (updateAddress()) {
        timeoutFailures = ioFailures = 0;
      }

      if (exception instanceof ConnectTimeoutException) {
        if (maxRetries >= 0 && currentFailures >= maxRetries) {
          throw exception;
        }
        LOG.info("Retrying connect to server: " + server + ". Already tried "
            + currentFailures + " time(s); maxRetries=" + maxRetries);
        throw exception;
      }

      handleConnectionFailureInternal(currentFailures, exception);
    }

    private void handleConnectionFailureInternal(int curRetries, IOException ioe) throws IOException {
      final RetryAction action;
      try {
        action = connectionRetryPolicy.shouldRetry(ioe, curRetries, 0, true);
      } catch (Exception e) {
        throw (e instanceof IOException) ? (IOException) e : new IOException(e);
      }

      if (action.action == RetryAction.RetryDecision.FAIL) {
        if (action.reason != null) {
          LOG.warn("Failed to connect to server: " + server + ": " + action.reason, ioe);
        }
        throw ioe;
      }

      if (Thread.currentThread().isInterrupted()) {
        LOG.warn("Interrupted while trying for connection");
        throw ioe;
      }

      try {
        Thread.sleep(action.delayMillis);
      } catch (InterruptedException e) {
        throw (IOException) new InterruptedIOException("Interrupted: action="
            + action + ", retry policy=" + connectionRetryPolicy).initCause(e);
      }

      LOG.info("Retrying connect to server: " + server + ". Already tried "
          + curRetries + " time(s); retry policy is " + connectionRetryPolicy);
    }

