  private DatanodeDescriptor findBestMatchNode(String networkLocation, String host) {
    List<Node> rackNodes = getNetworkTopology().getDatanodesInRack(networkLocation);
    if (rackNodes == null) {
      return (DatanodeDescriptor) getNetworkTopology().chooseRandom(NodeBase.ROOT);
    }

    // Try something machine local.
    for (Node rackNode : rackNodes) {
      if (((DatanodeDescriptor) rackNode).getIpAddr().equals(host)) {
        return (DatanodeDescriptor) rackNode;
      }
    }

    // Try something rack local.
    if (!rackNodes.isEmpty()) {
      return (DatanodeDescriptor) rackNodes
          .get(DFSUtil.getRandom().nextInt(rackNodes.size()));
    }

    // If we can't even choose rack local, just choose any node in the cluster.
    return (DatanodeDescriptor) getNetworkTopology().chooseRandom(NodeBase.ROOT);
  }
