try ( FSImage prevStateVar = prevState ) {
  prevStateVar.getStorage().layoutVersion = HdfsConstants.NAMENODE_LAYOUT_VERSION;
  for (Iterator<StorageDirectory> it = storage.dirIterator(false); it.hasNext();) {
    StorageDirectory sd = it.next();
    if (NNUpgradeUtil.canRollBack(sd, storage, prevStateVar.getStorage(), HdfsConstants.NAMENODE_LAYOUT_VERSION)) {
      LOG.info("Can perform rollback for " + sd);
      canRollback = true;
    }
  }

  if (fsns.isHaEnabled()) {
    // If HA is enabled, check if the shared log can be rolled back as well.
    editLog.initJournalsForWrite();
    boolean canRollBackSharedEditLog = editLog.canRollBackSharedLog(
        prevStateVar.getStorage(), HdfsConstants.NAMENODE_LAYOUT_VERSION);
    if (canRollBackSharedEditLog) {
      LOG.info("Can perform rollback for shared edit log.");
      canRollback = true;
    }
  }

  if (!canRollback)
    throw new IOException("Cannot rollback. None of the storage "
        + "directories contain previous fs state.");

  // Now that we know all directories are going to be consistent
  // Do rollback for each directory containing previous state
  for (Iterator<StorageDirectory> it = storage.dirIterator(false); it.hasNext();) {
    StorageDirectory sd = it.next();
    if (NNUpgradeUtil.canRollBack(sd, storage, prevStateVar.getStorage(), HdfsConstants.NAMENODE_LAYOUT_VERSION)) {
      LOG.info("Rolling back storage directory " + sd.getRoot()
               + ".\n   new LV = " + prevStateVar.getStorage().getLayoutVersion()
               + "; new CTime = " + prevStateVar.getStorage().getCTime());
      NNUpgradeUtil.doRollBack(sd);
    }
  }
  if (fsns.isHaEnabled()) {
    // If HA is enabled, try to roll back the shared log as well.
    editLog.doRollback();
  }

  isUpgradeFinalized = true;
