  private EditLogOpResult readAndProcessOp(EditLogInputStream in, long expectedTxId,
      long[] recentOpcodeOffsets, long numEdits, MetaRecoveryContext recovery,
      EnumMap<FSEditLogOpCodes, Holder<Integer>> opCounts, StartupOption startOpt,
      FSDirectory fsDir, FSNamesystem fsNamesys, long lastInodeId) throws IOException {
    FSEditLogOp op;
    try {
      op = in.readOp();
      if (op == null) {
        return new EditLogOpResult(null, true);
      }
    } catch (Throwable e) {
      // Handle a problem with our input
      check203UpgradeFailure(in.getVersion(true), e);
      String errorMessage =
        formatEditLogReplayError(in, recentOpcodeOffsets, expectedTxId);
      FSImage.LOG.error(errorMessage, e);
      if (recovery == null) {
         // We will only try to skip over problematic opcodes when in
         // recovery mode.
        throw new EditLogInputException(errorMessage, e, numEdits);
      }
      MetaRecoveryContext.editLogLoaderPrompt(
          "We failed to read txId " + expectedTxId,
          recovery, "skipping the bad section in the log");
      in.resync();
      return new EditLogOpResult(null, false);
    }

    if (op.hasTransactionId()) {
      if (op.getTransactionId() > expectedTxId) { 
        MetaRecoveryContext.editLogLoaderPrompt("There appears " +
            "to be a gap in the edit log.  We expected txid " +
            expectedTxId + ", but got txid " +
            op.getTransactionId() + ".", recovery, "ignoring missing " +
            " transaction IDs");
      } else if (op.getTransactionId() < expectedTxId) { 
        MetaRecoveryContext.editLogLoaderPrompt("There appears " +
            "to be an out-of-order edit in the edit log.  We " +
            "expected txid " + expectedTxId + ", but got txid " +
            op.getTransactionId() + ".", recovery,
            "skipping the out-of-order edit");
        return new EditLogOpResult(null, false);
      }
    }
    return new EditLogOpResult(op, false);
  }

  static class EditLogOpResult {
    final FSEditLogOp op;
    final boolean shouldBreak;

    EditLogOpResult(FSEditLogOp op, boolean shouldBreak) {
      this.op = op;
      this.shouldBreak = shouldBreak;
    }
  }

