/* Renamed the complex rename method to reduce cyclomatic complexity */
public boolean rename(Path src, Path dst) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Rename path {} to {}", src, dst);
    }

    String srcKey = pathToKey(src);
    String dstKey = pathToKey(dst);

    if (srcKey.isEmpty() || dstKey.isEmpty()) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("rename: src or dst are empty");
      }
      return false;
    }

    S3AFileStatus srcStatus;
    try {
      srcStatus = getFileStatus(src);
    } catch (FileNotFoundException e) {
      LOG.error("rename: src not found {}", src);
      return false;
    }

    if (srcKey.equals(dstKey)) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("rename: src and dst refer to the same file or directory");
      }
      return srcStatus.isFile();
    }

    S3AFileStatus dstStatus = null;
    try {
      dstStatus = getFileStatus(dst);
    } catch (FileNotFoundException e) {
      if (!validateDstParentExists(dst)) {
        return false;
      }
    }

    if (dstStatus != null && !validateRenameTarget(srcStatus, dstStatus)) {
      return false;
    }

    if (srcStatus.isFile()) {
      return renameFile(src, dst, srcKey, dstKey, dstStatus);
    } else {
      return renameDirectory(src, dst, srcKey, dstKey, dstStatus);
    }
}

/* Extracted directory validation logic */
private boolean validateDstParentExists(Path dst) throws IOException {
    Path parent = dst.getParent();
    if (pathToKey(parent).isEmpty()) {
      return false;
    }

    try {
      S3AFileStatus dstParentStatus = getFileStatus(dst.getParent());
      return dstParentStatus.isDirectory();
    } catch (FileNotFoundException e2) {
      return false;
    }
}

/* Extracted rename target validation */
private boolean validateRenameTarget(S3AFileStatus srcStatus, S3AFileStatus dstStatus) {
    if (srcStatus.isDirectory() && dstStatus.isFile()) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("rename: src is a directory and dst is a file");
      }
      return false;
    }

    return !(dstStatus.isDirectory() && !dstStatus.isEmptyDirectory());
}

/* Extracted file rename logic */
private boolean renameFile(Path src, Path dst, String srcKey, String dstKey, S3AFileStatus dstStatus) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("rename: renaming file " + src + " to " + dst);
    }

    try {
      if (dstStatus != null && dstStatus.isDirectory()) {
        String newDstKey = dstKey;
        if (!newDstKey.endsWith("/")) {
          newDstKey = newDstKey + "/";
        }
        String filename = srcKey.substring(pathToKey(src.getParent()).length() + 1);
        newDstKey = newDstKey + filename;
        copyFile(srcKey, newDstKey);
      } else {
        copyFile(srcKey, dstKey);
      }
      delete(src, false);
      return true;
    } catch (Exception e) {
      LOG.error("rename failed for file: " + src, e);
      return false;
    }
}

/* Extracted directory rename logic */
private boolean renameDirectory(Path src, Path dst, String srcKey, String dstKey, S3AFileStatus dstStatus) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("rename: renaming directory " + src + " to " + dst);
    }

    if (!dstKey.endsWith("/")) {
      dstKey = dstKey + "/";
    }

    if (!srcKey.endsWith("/")) {
      srcKey = srcKey + "/";
    }

    if (dstKey.startsWith(srcKey)) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("cannot rename a directory to a subdirectory of self");
      }
      return false;
    }

    List<DeleteObjectsRequest.KeyVersion> keysToDelete = new ArrayList<>();
    if (dstStatus != null && dstStatus.isEmptyDirectory()) {
      keysToDelete.add(new DeleteObjectsRequest.KeyVersion(dstKey));
    }

    copyDirectoryContents(srcKey, dstKey, keysToDelete);
    delete(src, true);

    if (src.getParent() != dst.getParent()) {
      deleteUnnecessaryFakeDirectories(dst.getParent());
      createFakeDirectoryIfNecessary(src.getParent());
    }
    return true;
}

/* Extracted directory copying logic */
private void copyDirectoryContents(String srcKey, String dstKey, List<DeleteObjectsRequest.KeyVersion> keysToDelete) throws IOException {
    ListObjectsRequest request = new ListObjectsRequest();
    request.setBucketName(bucket);
    request.setPrefix(srcKey);
    request.setMaxKeys(maxKeys);

    ObjectListing objects = s3.listObjects(request);
    statistics.incrementReadOps(1);

    while (true) {
      for (S3ObjectSummary summary : objects.getObjectSummaries()) {
        keysToDelete.add(new DeleteObjectsRequest.KeyVersion(summary.getKey()));
        String newDstKey = dstKey + summary.getKey().substring(srcKey.length());
        copyFile(summary.getKey(), newDstKey);

        if (keysToDelete.size() == MAX_ENTRIES_TO_DELETE) {
          processBatchDelete(keysToDelete);
        }
      }

      if (objects.isTruncated()) {
        objects = s3.listNextBatchOfObjects(objects);
        statistics.incrementReadOps(1);
      } else {
        if (keysToDelete.size() > 0) {
          processBatchDelete(keysToDelete);
        }
        break;
      }
    }
}

/* Extracted batch delete processing */
private void processBatchDelete(List<DeleteObjectsRequest.KeyVersion> keysToDelete) throws IOException {
    DeleteObjectsRequest deleteRequest = new DeleteObjectsRequest(bucket).withKeys(keysToDelete);
    s3.deleteObjects(deleteRequest);
    statistics.incrementWriteOps(1);
    keysToDelete.clear();
}

