public RemoteIterator<LocatedFileStatus> listFiles(
    final Path f, final boolean recursive) throws AccessControlException,
    FileNotFoundException, UnsupportedFileSystemException, 
    IOException {
  return new RemoteIterator<LocatedFileStatus>() {
    private Stack<RemoteIterator<LocatedFileStatus>> itors = 
      new Stack<RemoteIterator<LocatedFileStatus>>();
    RemoteIterator<LocatedFileStatus> curItor = listLocatedStatus(f);
    LocatedFileStatus curFile;

    @Override
    public boolean hasNext() throws IOException {
      while (curFile == null) {
        if (curItor.hasNext()) {
          handleFileStat(curItor.next());
        } else if (!itors.empty()) {
          curItor = itors.pop();
        } else {
          return false;
        }
      }
      return true;
    }

    private void handleFileStat(LocatedFileStatus stat)
    throws IOException {
      if (stat.isFile()) {
        curFile = stat;
      } else if (stat.isSymlink()) {
        resolveAndHandleSymlink(stat);
      } else if (recursive) {
        traverseDirectory(stat);
      }
    }

    private void resolveAndHandleSymlink(LocatedFileStatus stat)
        throws IOException {
      FileStatus symstat = FileContext.this.getFileStatus(stat.getSymlink());
      if (symstat.isFile()) {
        curFile = convertToLocated(symstat);
      } else if (symstat.isDirectory() && recursive) {
        itors.push(curItor);
        curItor = listLocatedStatus(stat.getPath());
      }
    }

    private void traverseDirectory(LocatedFileStatus stat) {
      itors.push(curItor);
      curItor = listLocatedStatus(stat.getPath());
    }

    private LocatedFileStatus convertToLocated(FileStatus status)
        throws IOException {
      if (status instanceof LocatedFileStatus) {
        return (LocatedFileStatus) status;
      }
      // Need block locations for files; use getFileBlockLocations
      BlockLocation[] locations = getFileBlockLocations(status.getPath(), 0,
          status.getLen());
      return new LocatedFileStatus(status, locations);
    }

    @Override
    public LocatedFileStatus next() throws IOException {
      if (hasNext()) {
        LocatedFileStatus result = curFile;
        curFile = null;
        return result;
      } 
      throw new java.util.NoSuchElementException("No more entry in " + f);
    }
  };
}

