  private int decodeRunLength(final int firstRunSym, final int eob,
                               final int groupNo, final int groupPos,
                               final int[] base_zt, final int[] limit_zt,
                               final int[] perm_zt, final int minLens_zt,
                               final int bsBuffShadow, final int bsLiveShadow,
                               final InputStream inShadow) throws IOException {
    int s = -1;
    int n = 1;
    int nextSym = firstRunSym;
    int bsBuffLocal = bsBuffShadow;
    int bsLiveLocal = bsLiveShadow;
    int groupNoLocal = groupNo;
    int groupPosLocal = groupPos;

    while (true) {
      if (nextSym == RUNA) {
        s += n;
      } else if (nextSym == RUNB) {
        s += n << 1;
      } else {
        break;
      }

      n <<= 1;

      if (groupPosLocal == 0) {
        groupPosLocal = G_SIZE - 1;
        int zt = this.data.selector[++groupNoLocal] & 0xff;
        int[] base_zt_local = this.data.base[zt];
        int[] limit_zt_local = this.data.limit[zt];
        int[] perm_zt_local = this.data.perm[zt];
        int minLens_zt_local = this.data.minLens[zt];

        nextSym = decodeHuffmanSymbol(nextSym, bsBuffLocal, bsLiveLocal, inShadow,
            minLens_zt_local, base_zt_local, limit_zt_local, perm_zt_local);
      } else {
        groupPosLocal--;
        nextSym = decodeHuffmanSymbol(nextSym, bsBuffLocal, bsLiveLocal, inShadow,
            minLens_zt, base_zt, limit_zt, perm_zt);
      }
    }

    this.bsBuff = bsBuffLocal;
    this.bsLive = bsLiveLocal;
    return s;
  }

  private int decodeHuffmanSymbol(int nextSym, final int bsBuffLocal, final int bsLiveLocal,
                                  final InputStream inShadow, final int minLens,
                                  final int[] base, final int[] limit, final int[] perm) throws IOException {
    int zn = minLens;
    int zvec = (bsBuffLocal >> (bsLiveLocal - zn)) & ((1 << zn) - 1);
    int bsLiveShadow = bsLiveLocal - zn;

    while (zvec > limit[zn]) {
      zn++;
      while (bsLiveShadow < 1) {
        final int thech = readAByte(inShadow);
        if (thech >= 0) {
          bsBuffLocal = (bsBuffLocal << 8) | thech;
          bsLiveShadow += 8;
        } else {
          throw new IOException("unexpected end of stream");
        }
      }
      bsLiveShadow--;
      zvec = (zvec << 1)
          | ((bsBuffLocal >> bsLiveShadow) & 1);
    }
    return perm[(int) (zvec - base[zn])];
  }

  private int getAndMoveToFrontDecode0(final int groupNo) throws IOException {
    final InputStream inShadow = this.in;
    final Data dataShadow = this.data;
    final int zt = dataShadow.selector[groupNo] & 0xff;
    final int[] limit_zt = dataShadow.limit[zt];
    int zn = dataShadow.minLens[zt];
    int zvec = (int) bsR(zn);
    int bsLiveShadow = (int) this.bsLive;
    int bsBuffShadow = (int) this.bsBuff;

    while (zvec > limit_zt[zn]) {
      zn++;
      while (bsLiveShadow < 1) {
        final int thech = readAByte(inShadow);

        if (thech >= 0) {
          bsBuffShadow = (bsBuffShadow << 8) | thech;
          bsLiveShadow += 8;
          continue;
        } else {
          throw new IOException("unexpected end of stream");
        }
      }
      bsLiveShadow--;
      zvec = (zvec << 1) | ((bsBuffShadow >> bsLiveShadow) & 1);
    }

    this.bsLive = bsLiveShadow;
    this.bsBuff = bsBuffShadow;

    return dataShadow.perm[zt][zvec - dataShadow.base[zt][zn]];
  }

  private void setupBlock() throws IOException {
    if (this.data == null) {
      return;
    }

    final int[] cftab = this.data.cftab;
    final int[] tt = this.data.initTT(this.last + 1);
    final byte[] ll8 = this.data.ll8;
    cftab[0] = 0;
    System.arraycopy(this.data.unzftab, 0, cftab, 1, 256);

    for (int i = 1, c = cftab[0]; i <= 256; i++) {
      c += cftab[i];
      cftab[i] = c;
    }

    for (int i = 0, lastShadow = this.last; i <= lastShadow; i++) {
      tt[cftab[ll8[i] & 0xff]++] = i;
