class Dumper implements Runnable {
    /** Dump data into a file */
    private void dump() {
        restoreDump outputStreamRestore = createDumpOutputStream();
        if (outputStreamRestore == null) {
            return;
        }

        RandomAccessFile randomAccessFile = restoreDumpFile(outputStreamRestore.getDumpFile());
        if (randomAccessFile == null) {
            return;
        }

        if (LOG.isDebugEnabled()) {
            LOG.debug("Start dump. Before dump, nonSequentialWriteInMemory == "
                + nonSequentialWriteInMemory.get());
        }

        Iterator<OffsetRange> it = pendingWrites.keySet().iterator();
        while (activeState && it.hasNext()
            && nonSequentialWriteInMemory.get() > 0) {
            OffsetRange key = it.next();
            WriteCtx writeCtx = pendingWrites.get(key);
            if (writeCtx == null) {
                continue;
            }
            try {
                long dumpedDataSize = writeCtx.dumpData(outputStreamRestore.getDumpOut(), randomAccessFile);
                if (dumpedDataSize > 0) {
                    updateNonSequentialWriteInMemory(-dumpedDataSize);
                }
            } catch (IOException e) {
                LOG.error("Dump data failed: " + writeCtx + " with error: " + e
                    + " OpenFileCtx state: " + activeState);
                enabledDump = false;
                closeResources(outputStreamRestore.getDumpOut(), randomAccessFile);
                return;
            }
        }

        if (LOG.isDebugEnabled()) {
            LOG.debug("After dump, nonSequentialWriteInMemory == "
                + nonSequentialWriteInMemory.get());
        }

        closeResources(outputStreamRestore.getDumpOut(), randomAccessFile);
    }

    private RestoreDump createDumpOutputStream() {
        if (dumpOut != null) {
            return new RestoreDump(dumpOut, null);
        }

        LOG.info("Create dump file: " + dumpFilePath);
        File dumpFile = new File(dumpFilePath);
        try {
            synchronized (this) {
                if (!dumpFile.createNewFile()) {
                    LOG.error("The dump file should not exist: " + dumpFilePath);
                    return null;
                }
                dumpOut = new FileOutputStream(dumpFile);
                return new RestoreDump(dumpOut, dumpFile);
            }
        } catch (IOException e) {
            LOG.error("Got failure when creating dump stream " + dumpFilePath, e);
            enabledDump = false;
            closeResources(dumpOut, null);
            dumpOut = null;
            return null;
        }
    }

    private RandomAccessFile restoreDumpFile(File dumpFile) {
        if (raf != null) {
            return raf;
        }

        if (dumpFile == null) {
            dumpFile = new File(dumpFilePath);
        }
        try {
            raf = new RandomAccessFile(dumpFile, "r");
            return raf;
        } catch (FileNotFoundException e) {
            LOG.error("Can't get random access to file " + dumpFilePath);
            enabledDump = false;
            return null;
        }
    }

    private void closeResources(FileOutputStream out, RandomAccessFile raf) {
        if (out != null) {
            try {
                out.close();
            } catch (IOException e) {
                LOG.error("Can't close dump stream " + dumpFilePath, e);
            }
        }

        if (raf != null) {
            try {
                raf.close();
            } catch (IOException e) {
                LOG.error("Got exception when closing input stream of dump file.", e);
            }
        }
    }

    private static class RestoreDump {
        private final FileOutputStream dumpOut;
        private final File dumpFile;

        public RestoreDump(FileOutputStream dumpOut, File dumpFile) {
            this.dumpOut = dumpOut;
            this.dumpFile = dumpFile;
        }

        public FileOutputStream getDumpOut() {
            return dumpOut;
        }

        public File getDumpFile() {
            return dumpFile;
        }
    }

    @Override
    public void run() {
        while (activeState && enabledDump) {
            try {
                if (nonSequentialWriteInMemory.get() >= DUMP_WRITE_WATER_MARK) {
                    dump();
                }
                synchronized (OpenFileCtx.this) {
                    if (nonSequentialWriteInMemory.get() < DUMP_WRITE_WATER_MARK) {
                        OpenFileCtx.this.notifyAll();
                        try {
                            OpenFileCtx.this.wait();
                            if (LOG.isDebugEnabled()) {
                                LOG.debug("Dumper woke up");
                            }
                        } catch (InterruptedException e) {
                            LOG.info("Dumper is interrupted, dumpFilePath= "
                                + OpenFileCtx.this.dumpFilePath);
                        }
                    }
                }
                if (LOG.isDebugEnabled()) {
                    LOG.debug("Dumper checking OpenFileCtx activeState: " + activeState
                        + " enabledDump: " + enabledDump);
                }
            } catch (Throwable t) {
                synchronized (OpenFileCtx.this) {
                    OpenFileCtx.this.notifyAll();
                }
                LOG.info("Dumper get Throwable: " + t + ". dumpFilePath: "
                    + OpenFileCtx.this.dumpFilePath, t);
                activeState = false;
            }
        }
    }
