  synchronized long rollEditLog() throws IOException {
    LOG.info("Rolling edit logs");
    endCurrentLogSegment(true);

    long nextTxId = getLastWrittenTxId() + 1;
    startLogSegment(nextTxId, true);

    assert curSegmentTxId == nextTxId;
