	/**
	 * The main method of the jEdit application.
	 * This should never be invoked directly.
	 * @param args The command line arguments
	 */
	public static void main(String[] args)
	{
		try
		{
			checkJavaVersion();
			handleCommandLineArgs(args);
			Log.init(true, getLogLevel(args));

			if (tryConnectToRunningInstance(args))
				return;

			prepareSettingsDirectory();
			setupServer();

			initApplication();

			SwingUtilities.invokeLater(() -> {
				runApplicationStartup(args);
			});
		}
		catch (Exception e)
		{
			Log.log(Log.ERROR, jEdit.class, "Fatal error occurred: " + e.getMessage());
			Log.log(Log.ERROR, jEdit.class, e);
			System.exit(1);
		}
	}

	private static void checkJavaVersion()
	{
		String javaVersion = System.getProperty("java.version");
		if(javaVersion.compareTo("1.3") < 0)
		{
			System.err.println("You are running Java version "
				+ javaVersion + ".");
			System.err.println("jEdit requires Java 1.3 or later.");
			System.exit(1);
		}
	}

	private static int getLogLevel(String[] args)
	{
		int level = Log.WARNING;
		if(args.length >= 1)
		{
			String levelStr = args[0];
			if(levelStr.length() == 1 && Character.isDigit(
				levelStr.charAt(0)))
			{
				level = Integer.parseInt(levelStr);
				args[0] = null;
			}
		}
		return level;
	}

	private static void handleCommandLineArgs(String[] args)
	{
		boolean endOpts = false;
		settingsDirectory = MiscUtilities.constructPath(
			System.getProperty("user.home"),".jedit");
		String portFile = "server";

		for(int i = 0; i < args.length; i++)
		{
			String arg = args[i];
			if(arg == null)
				continue;
			else if(arg.length() == 0)
				args[i] = null;
			else if(arg.startsWith("-") && !endOpts)
			{
				if(arg.equals("--"))
					endOpts = true;
				else if(arg.equals("-usage"))
				{
					version();
					System.err.println();
					usage();
					System.exit(1);
				}
				else if(arg.equals("-version"))
				{
					version();
					System.exit(1);
				}
				else if(arg.equals("-nosettings"))
					settingsDirectory = null;
				else if(arg.startsWith("-settings="))
					settingsDirectory = arg.substring(10);
				else if(arg.startsWith("-noserver"))
					portFile = null;
				else if(arg.equals("-server"))
					portFile = "server";
				else if(arg.startsWith("-server="))
					portFile = arg.substring(8);
				else if(arg.startsWith("-background"))
					background = true;
				else if(arg.equals("-nogui"))
					GUIUtilities.showSplashScreen();
				else if(arg.equals("-norestore"))
					// restore = false; // Not needed here
				else if(arg.startsWith("-run="))
					// scriptFile handling moved to runApplicationStartup
				else
				{
					System.err.println("Unknown option: " + arg);
					usage();
					System.exit(1);
				}
				args[i] = null;
			}
		}
	}

	private static boolean tryConnectToRunningInstance(String[] args)
	{
		if(settingsDirectory == null)
			return false;

		String portFile = MiscUtilities.constructPath(settingsDirectory, "server");
		if(!new File(portFile).exists())
			return false;

		try
		{
			BufferedReader in = new BufferedReader(new FileReader(portFile));
			String check = in.readLine();
			if(!check.equals("b"))
				throw new Exception("Wrong port file format");

			int port = Integer.parseInt(in.readLine());
			int key = Integer.parseInt(in.readLine());
			in.close();

			Socket socket = new Socket(InetAddress.getByName("127.0.0.1"),port);
			DataOutputStream out = new DataOutputStream(
				socket.getOutputStream());
			out.writeInt(key);

			String script = makeServerScript(true, args, null);
			out.writeUTF(script);
			out.close();

			System.exit(0);
			return true;
		}
		catch(Exception e)
		{
			Log.log(Log.NOTICE,jEdit.class,"An error occurred while connecting to the jEdit server instance.");
			return false;
		}
	}

	private static void prepareSettingsDirectory()
	{
		if(settingsDirectory == null)
			return;

		File _settingsDirectory = new File(settingsDirectory);
		if(!_settingsDirectory.exists())
			_settingsDirectory.mkdirs();

		File _macrosDirectory = new File(settingsDirectory,"macros");
		if(!_macrosDirectory.exists())
			_macrosDirectory.mkdir();

		String logPath = MiscUtilities.constructPath(settingsDirectory,"activity.log");
		backupSettingsFile(new File(logPath));

		try
		{
			Writer stream = new BufferedWriter(new FileWriter(logPath));
			Log.setLogWriter(stream);
		}
		catch(Exception e)
		{
			Log.log(Log.ERROR,jEdit.class,e);
		}
	}

	private static void setupServer()
	{
		if(settingsDirectory != null)
		{
			String portFile = MiscUtilities.constructPath(settingsDirectory,"server");
			server = new EditServer(portFile);
			if(!server.isOK())
				server = null;
		}
	}

	private static void initApplication()
	{
		initMisc();
		initSystemProperties();
		if(jEditHome != null)
			initSiteProperties();
		GUIUtilities.advanceSplashProgress();

		BeanShell.init();
		initUserProperties();
		initPLAF();

		if(OperatingSystem.hasJava14() && System.getProperty("jedit.nojava14") == null)
		{
			try
			{
				ClassLoader loader = jEdit.class.getClassLoader();
				Class clazz;
				if(loader != null)
					clazz = loader.loadClass("org.gjt.sp.jedit.Java14");
				else
					clazz = Class.forName("org.gjt.sp.jedit.Java14");
				java.lang.reflect.Method meth = clazz.getMethod("init",new Class[0]);
				meth.invoke(null,new Object[0]);
			}
			catch(Exception e)
			{
				Log.log(Log.ERROR,jEdit.class,e);
				System.exit(1);
			}
		}

		initActions();
		initDockables();
		VFSManager.init();
		propertiesChanged();
	}

	private static void runApplicationStartup(String[] args)
	{
		EditBus.send(new EditorStarted(null));

		String scriptFile = extractScriptFile(args);
		String userDir = System.getProperty("user.dir");

		Buffer buffer = openFiles(null, userDir, args);
		if(buffer != null)
		{
			View view = newView(null, buffer);
			GUIUtilities.hideSplashScreen();
			return;
		}

		String splitConfig = restoreOpenFiles();
		if(splitConfig == null && getBooleanProperty("restore"))
			splitConfig = restoreOpenFiles();

		if(bufferCount == 0)
			newFile(null);

		View view = newView(null, splitConfig);

		VFSManager.start();
		if(server != null)
			server.start();

		GUIUtilities.hideSplashScreen();
		Log.log(Log.MESSAGE,jEdit.class,"Startup complete");

		handlePluginErrors();
		runStartupScripts(userDir, scriptFile);
	}

	private static String extractScriptFile(String[] args)
	{
		for(int i = 0; i < args.length; i++)
		{
			if(args[i] != null && args[i].startsWith("-run="))
				return args[i].substring(5);
		}
		return null;
	}

	private static void handlePluginErrors()
	{
		if(pluginErrors != null && !pluginErrors.isEmpty())
		{
			String caption = jEdit.getProperty("plugin-error.caption" + (pluginErrors.size() == 1 ? "-1" : ""),new Integer[] { new Integer(pluginErrors.size()) });
			new ErrorListDialog(jEdit.getFirstView(), jEdit.getProperty("plugin-error.title"), caption, pluginErrors, true);
			pluginErrors.removeAllElements();
		}
	}

	private static void runStartupScripts(String userDir, String scriptFile)
	{
		if(!noStartupScripts && jEditHome != null)
		{
			String path = MiscUtilities.constructPath(jEditHome,"startup");
			File file = new File(path);
			if(file.exists())
				runStartupScripts(file);
		}

		if(!noStartupScripts && settingsDirectory != null)
		{
			String path = MiscUtilities.constructPath(settingsDirectory,"startup");
			File file = new File(path);
			if(!file.exists())
				file.mkdirs();
			else
				runStartupScripts(file);
		}

		if(scriptFile != null)
		{
			scriptFile = MiscUtilities.constructPath(userDir,scriptFile);
			BeanShell.runScript(null,scriptFile,null,false);
		}
	}
