	//{{{ main() method
	/**
	 * The main method of the jEdit application.
	 * This should never be invoked directly.
	 * @param args The command line arguments
	 */
	public static void main(String[] args)
	{
		String javaVersion = System.getProperty("java.version");
		if(javaVersion.compareTo("1.3") < 0)
		{
			System.err.println("You are running Java version "
				+ javaVersion + ".");
			System.err.println("jEdit requires Java 1.3 or later.");
			System.exit(1);
		}

		CommandlineOptions options = parseCommandlineOptions(args);
		Log.init(true, options.logLevel);

		if (!tryConnectToRunningInstance(options.portFile))
		{
			prepareSettingsDirectory(options.settingsDirectory);
			Log.setLogWriter(createLogWriter(options.settingsDirectory));

			Log.log(Log.NOTICE,jEdit.class,"jEdit version " + getVersion());
			Log.log(Log.MESSAGE,jEdit.class,"Settings directory is "
				+ options.settingsDirectory);

			prepareServer(options.portFile, options.background);
			performInitialization();
			runStartupScripts(options);
			executeScriptIfSpecified(options.scriptFile, options.userDir);
			Buffer buffer = openFiles(null, options.userDir, args);
			String splitConfig = restoreOpenFilesIfNecessary(buffer, options);
			createViewWithBuffer(buffer, splitConfig, options.gui);
		}
	} //}}}

	//{{{ parseCommandlineOptions method
	private static CommandlineOptions parseCommandlineOptions(String[] args)
	{
		CommandlineOptions options = new CommandlineOptions();

		// Parse log level from first argument
		if (args.length >= 1)
		{
			String levelStr = args[0];
			if (levelStr.length() == 1 && Character.isDigit(levelStr.charAt(0)))
			{
				options.logLevel = Integer.parseInt(levelStr);
				args[0] = null;
			}
		}

		// Set up defaults
		options.settingsDirectory = MiscUtilities.constructPath(
			System.getProperty("user.home"),".jedit");
		options.portFile = "server";
		options.restore = true;
		options.gui = true;
		options.background = false;
		options.noPlugins = false;
		options.noStartupScripts = false;
		options.userDir = System.getProperty("user.dir");
		options.scriptFile = null;

		// Parse command line options
		boolean endOpts = false;
		for(int i = 0; i < args.length; i++)
		{
			String arg = args[i];
			if(arg == null)
				continue;
			else if(arg.length() == 0)
				args[i] = null;
			else if(arg.startsWith("-") && !endOpts)
			{
				if(arg.equals("--"))
					endOpts = true;
				else if(arg.equals("-usage"))
				{
					version();
					System.err.println();
					usage();
					System.exit(1);
				}
				else if(arg.equals("-version"))
				{
					version();
					System.exit(1);
				}
				else if(arg.equals("-nosettings"))
					options.settingsDirectory = null;
				else if(arg.startsWith("-settings="))
					options.settingsDirectory = arg.substring(10);
				else if(arg.startsWith("-noserver"))
					options.portFile = null;
				else if(arg.equals("-server"))
					options.portFile = "server";
				else if(arg.startsWith("-server="))
					options.portFile = arg.substring(8);
				else if(arg.startsWith("-background"))
					options.background = true;
				else if(arg.equals("-nogui"))
					options.gui = false;
				else if(arg.equals("-norestore"))
					options.restore = false;
				else if(arg.equals("-noplugins"))
					options.noPlugins = true;
				else if(arg.equals("-nostartupscripts"))
					options.noStartupScripts = true;
				else if(arg.startsWith("-run="))
					options.scriptFile = arg.substring(5);
				else
				{
					System.err.println("Unknown option: " + arg);
					usage();
					System.exit(1);
				}
				args[i] = null;
			}
		}

		if (options.settingsDirectory != null && options.portFile != null)
			options.portFile = MiscUtilities.constructPath(options.settingsDirectory, options.portFile);
		else
			options.portFile = null;

		return options;
	}
