	//{{{ prepareSettingsDirectory method
	private static void prepareSettingsDirectory(String settingsDirectory)
	{
		if (settingsDirectory == null)
			return;

		File dir = new File(settingsDirectory);
		if (!dir.exists())
			dir.mkdirs();

		File macrosDir = new File(settingsDirectory,"macros");
		if (!macrosDir.exists())
			macrosDir.mkdir();
	}
	//}}} 

	//{{{ createLogWriter method
	private static Writer createLogWriter(String settingsDirectory)
	{
		if (settingsDirectory == null)
			return null;

		String logPath = MiscUtilities.constructPath(settingsDirectory,"activity.log");
		backupSettingsFile(new File(logPath));

		try
		{
			return new BufferedWriter(new FileWriter(logPath));
		}
		catch(Exception e)
		{
			e.printStackTrace();
			return null;
		}
	}
	//}}} 

	//{{{ prepareServer method
	private static void prepareServer(String portFile, boolean background)
	{
		if(portFile != null)
		{
			server = new EditServer(portFile);
			if(!server.isOK())
				server = null;
		}
		else
		{
			if(background)
			{
				background = false;
				System.err.println("You cannot specify both the -background and -noserver switches");
			}
		}
	}
