	//{{{ runStartupScripts method
	private static void runStartupScripts(CommandlineOptions options)
	{
		if(!options.noStartupScripts)
		{
			if(jEditHome != null)
			{
				String path = MiscUtilities.constructPath(jEditHome,"startup");
				File file = new File(path);
				if(file.exists())
					runStartupScripts(file);
			}

			if(options.settingsDirectory != null)
			{
				String path = MiscUtilities.constructPath(options.settingsDirectory,"startup");
				File file = new File(path);
				if(!file.exists())
					file.mkdirs();
				else
					runStartupScripts(file);
			}
		}
	}
