	//{{{ restoreOpenFilesIfNecessary method
	private static String restoreOpenFilesIfNecessary(Buffer buffer, CommandlineOptions options)
	{
		String splitConfig = null;

		if(options.restore && options.settingsDirectory != null
			&& jEdit.getBooleanProperty("restore")
			&& (bufferCount == 0 || jEdit.getBooleanProperty("restore.cli")))
		{
			splitConfig = restoreOpenFiles();
		}

		if(bufferCount == 0 && options.gui)
			newFile(null);

		return splitConfig;
	}
