	*/
	private Object getDefaultPrimitiveOrNullValue(Class type) {
		if (!type.isPrimitive()) return Primitive.NULL;

		if (type == Boolean.TYPE) return new	Primitive(Boolean.FALSE);
		else if (type == Byte.TYPE) return new	Primitive((byte)0);
		else if (type == Short.TYPE) return new	Primitive((short)0);
		else if (type == Character.TYPE) return new	Primitive((char)0);
		else if (type == Integer.TYPE) return new	Primitive((int)0);
		else if (type == Long.TYPE) return new	Primitive(0L);
		else if (type == Float.TYPE) return new	Primitive(0.0f);
		else if (type == Double.TYPE) return new	Primitive(0.0d);
		else return Primitive.NULL;
	}

