    public void	setTypedVariable(
		String	name, Class type, Object value,	boolean	isFinal) 
		throws EvalError 
	{
		if (variables == null)
			variables =	new Hashtable();

		if (value == null)
		{
			value = getDefaultValueForType(type);
		}

		Object existing = getVariableImpl( name, false ); 
		if ( existing instanceof TypedVariable ) 
		{
			TypedVariable typedVar = (TypedVariable)existing;
			if ( typedVar.getType() != type )
				throw new EvalError( "Typed variable: "+name
					+" was previously declared with type: " 
					+ typedVar.getType() );
			else {
				typedVar.setValue( value );
				return;
			}
		}

		variables.put(name, new	TypedVariable(type, value, isFinal));
    }

    private Object getDefaultValueForType(Class type) throws EvalError {
		if ( !type.isPrimitive() )
			return Primitive.NULL;

		if ( type == Boolean.TYPE ) return new Primitive(Boolean.FALSE);
        if ( type == Byte.TYPE ) return new Primitive((byte)0);
        if ( type == Short.TYPE ) return new Primitive((short)0);
        if ( type == Character.TYPE ) return new Primitive((char)0);
        if ( type == Integer.TYPE ) return new Primitive((int)0);
        if ( type == Long.TYPE ) return new Primitive(0L);
        if ( type == Float.TYPE ) return new Primitive(0.0f);
        if ( type == Double.TYPE ) return new Primitive(0.0d);

		// Shouldn't happen since isPrimitive() guard is checked above
		throw new EvalError("Unsupported primitive type: " + type.getName());
    }

	/**
		Set the typed variable with the value.  
		An existing typed variable may only be set to the same type.
		If an untyped variable exists it will be overridden with the new
		typed var.
		The set will perform a getAssignableForm() on the value if necessary.

		<p>
		Note: this method is primarily intended for use internally.  If you use
		this method outside of the bsh package and wish to set variables with
		primitive values you will have to wrap them using bsh.Primitive.
		@see bsh.Primitive

		@param value If value is null, you'll get the default value for the type
    */
    public void	setTypedVariable(
		String	name, Class type, Object value,	boolean	isFinal) 
		throws EvalError 
	{
		if (variables == null)
			variables =	new Hashtable();

		if (value == null)
			value = getDefaultPrimitiveValue(type);

		// does the variable already exist?
		if ( variables.containsKey(name) ) 
		{
			Object existing = getVariableImpl( name, false );
			// is it typed?
			if ( existing instanceof TypedVariable ) 
			{
				TypedVariable typedVar = (TypedVariable)existing;
				// if it had a different type throw error
				if ( typedVar.getType() != type )
					throw new EvalError( "Typed variable: "+name
						+" was previously declared with type: " 
						+ typedVar.getType() );
				else {
					// else set it and return
					typedVar.setValue( value );
					return;
				}
			}
			// else fall through to override and install the new typed version
		} 

		// add the new typed var
		variables.put(name, new	TypedVariable(type, value, isFinal));
    }

	/**
		Returns the default value for the given Java type.
		For primitives, returns a Primitive wrapper with the default value.
		For non-primitives, returns Primitive.NULL.
	*/
    private Object getDefaultPrimitiveValue(Class type) {
		if (!type.isPrimitive())
			return Primitive.NULL;

		if (type == Boolean.TYPE)
			return new Primitive(Boolean.FALSE);
		else if (type == Byte.TYPE)
			return new Primitive((byte)0);
		else if (type == Short.TYPE)
			return new Primitive((short)0);
		else if (type == Character.TYPE)
			return new Primitive((char)0);
		else if (type == Integer.TYPE)
			return new Primitive((int)0);
		else if (type == Long.TYPE)
			return new Primitive(0L);
		else if (type == Float.TYPE)
			return new Primitive(0.0f);
		else if (type == Double.TYPE)
			return new Primitive(0.0d);
		// Should never reach here; added for completeness
		throw new InterpreterError("Unsupported primitive type: " + type.getName());
	}

