private static class PiePlotCloneBuilder {
    private final PiePlot source;

    PiePlotCloneBuilder(PiePlot source) {
        this.source = source;
    }

    PiePlot build() throws CloneNotSupportedException {
        PiePlot clone = (PiePlot) this.source.superClone();
        clone.sectionPaintMap = copyPaintMap(this.source.sectionPaintMap);
        clone.sectionOutlinePaintMap 
                = copyPaintMap(this.source.sectionOutlinePaintMap);
        clone.sectionOutlineStrokeMap 
                = copyStrokeMap(this.source.sectionOutlineStrokeMap);
        clone.explodePercentages = copyExplodePercentages(
                this.source.explodePercentages);
        copyIfCloneable(this.source.labelGenerator, clone,
                p -> clone.labelGenerator = p);
        copyIfCloneable(this.source.urlGenerator, clone,
                p -> clone.urlGenerator = p);
        copyIfCloneable(this.source.legendLabelGenerator, clone,
                p -> clone.legendLabelGenerator = p);
        copyIfCloneable(this.source.legendLabelToolTipGenerator, clone,
                p -> clone.legendLabelToolTipGenerator = p);
        copyIfCloneable(this.source.legendLabelURLGenerator, clone,
                p -> clone.legendLabelURLGenerator = p);
        clone.legendItemShape = ShapeUtilities.clone(
                this.source.legendItemShape);
        return clone;
    }

