        return new StrokeMap(original);
    }

    private Map<Comparable<?>, Number> copyExplodePercentages(
            Map<Comparable<?>, Number> original) {
        return original instanceof TreeMap
                ? new TreeMap<>(original)
                : new java.util.HashMap<>(original);
    }

    private <T> void copyIfCloneable(T original, PiePlot clone,
            java.util.function.Consumer<T> setter) {
        if (original == null) {
            return;
        }
        if (original instanceof PublicCloneable) {
            T copy = (T) ObjectUtilities.clone(original);
            setter.accept(copy);
        } else if (original instanceof PieSectionLabelGenerator) {
            // Fallback for known cloneable generator types
            PieSectionLabelGenerator gen
                    = (PieSectionLabelGenerator) original;
            PieSectionLabelGenerator copy
                    = new StandardPieSectionLabelGenerator(
                            gen.getFormatString(), gen.getDateFormat());
            setter.accept((T) copy);
        } else {
            setter.accept(original);
        }
    }
