        Insets insets = getInsets();
        Rectangle2D available = createAvailableArea(size, insets);

        boolean scale = determineScaling(available);
        Rectangle2D chartArea = createChartArea(available);

        if (this.useBuffer) {
            handleBufferedDrawing(g2, available, chartArea, scale);
        } else {
            handleDirectDrawing(g2, chartArea, scale, insets);
