	/**
	 * Forwards key events directly to the input handler.
	 * This is slightly faster than using a KeyListener
	 * because some Swing overhead is avoided.
	 */
	public void processKeyEvent(KeyEvent evt)
	{
		if(isClosed())
			return;

		if(getFocusOwner() instanceof JComponent)
		{
			JComponent comp = (JComponent)getFocusOwner();
			InputMap map = comp.getInputMap();
			ActionMap am = comp.getActionMap();

			if(map != null && am != null && comp.isEnabled())
			{
				Object binding = map.get(KeyStroke.getKeyStrokeForEvent(evt));
				if(binding != null && am.get(binding) != null)
				{
					return;
				}
			}
		}

		if(getFocusOwner() instanceof JTextComponent)
		{
			// fix for the bug where key events in JTextComponents
			// inside views are also handled by the input handler
			if(evt.getID() == KeyEvent.KEY_PRESSED)
			{
				if(isSpecialTextComponentKey(evt))
				{
					return;
				}
			}

			Keymap keymap = ((JTextComponent)getFocusOwner())
				.getKeymap();
			if(keymap.getAction(KeyStroke.getKeyStrokeForEvent(evt)) != null)
				return;
		}

		if(evt.isConsumed())
			return;

		evt = KeyEventWorkaround.processKeyEvent(evt);
		if(evt == null)
			return;

		handleKeyEvent(evt);
		if(!evt.isConsumed())
			super.processKeyEvent(evt);
	} //}}}

	/**
	 * Checks if the key event is a special text component key that should be ignored.
	 * @param evt the key event to check
	 * @return true if the key is a special text component key, false otherwise
	 */
	private static boolean isSpecialTextComponentKey(KeyEvent evt)
	{
		switch(evt.getKeyCode())
		{
		case KeyEvent.VK_BACK_SPACE:
		case KeyEvent.VK_TAB:
		case KeyEvent.VK_ENTER:
			return true;
		default:
			return false;
		}
	}

	/**
	 * Handles key events by dispatching to appropriate handlers based on event type.
	 * @param evt the key event to handle
	 */
	private void handleKeyEvent(KeyEvent evt)
	{
		if(evt.isConsumed())
			return;

		KeyEventDispatcher dispatcher = getKeyEventDispatcher(evt.getID());
		if(dispatcher != null)
		{
			dispatcher.dispatch(evt, this);
		}
	}

	/**
	 * Interface for dispatching key events based on event type.
	 */
	private interface KeyEventDispatcher
	{
		void dispatch(KeyEvent evt, View view);
	}

	/**
	 * Strategy object for handling KEY_TYPED events.
	 */
	private static class TypedEventDispatcher implements KeyEventDispatcher
	{
		public void dispatch(KeyEvent evt, View view)
		{
			// Handled in text area
			if(view.keyEventInterceptor != null)
				/* keyEventInterceptor.keyTyped(evt) */;
			else if(view.inputHandler.isPrefixActive()
				&& !view.getTextArea().hasFocus())
				view.inputHandler.keyTyped(evt);
		}
	}

	/**
	 * Strategy object for handling KEY_PRESSED events.
	 */
	private static class PressedEventDispatcher implements KeyEventDispatcher
	{
		public void dispatch(KeyEvent evt, View view)
		{
			if(view.keyEventInterceptor != null)
				view.keyEventInterceptor.keyPressed(evt);
			else
				view.inputHandler.keyPressed(evt);
		}
	}

	/**
	 * Strategy object for handling KEY_RELEASED events.
	 */
	private static class ReleasedEventDispatcher implements KeyEventDispatcher
	{
		public void dispatch(KeyEvent evt, View view)
		{
			if(view.keyEventInterceptor != null)
				view.keyEventInterceptor.keyReleased(evt);
			else
				view.inputHandler.keyReleased(evt);
		}
	}

	/**
	 * Returns the appropriate event dispatcher for the given event ID.
	 * @param eventID the key event ID
	 * @return the event dispatcher, or null if no dispatcher found
	 */
	private static KeyEventDispatcher getKeyEventDispatcher(int eventID)
	{
		switch(eventID)
		{
		case KeyEvent.KEY_TYPED:
			return new TypedEventDispatcher();
		case KeyEvent.KEY_PRESSED:
			return new PressedEventDispatcher();
		case KeyEvent.KEY_RELEASED:
			return new ReleasedEventDispatcher();
		default:
			return null;
		}
	}

