/**
 * Deep copies a Paint object if serializable, otherwise returns the original.
 *
 * @param paint  the paint instance.
 * @return the cloned paint or original if not serializable.
 */
private Paint deepCopyPaint(Paint paint) {
    if (paint == null) {
        return null;
    }
    if (paint instanceof Serializable) {
        try {
            return (Paint) SerialUtilities.readPaint(
                SerialUtilities.writePaintToStream(paint));
        } catch (Exception ignored) {
            return paint;
        }
    }
    return paint;
}

