    /**
     * Copies the state of this plot to the specified clone.
     *
     * @param clone  the clone (<code>null</code> not permitted).
     */
    private void copyStateTo(PolarPlot clone) throws CloneNotSupportedException {
        // Copy basic properties
        clone.angleTickUnit = this.angleTickUnit;
        clone.angleOffset = this.angleOffset;
        clone.counterClockwise = this.counterClockwise;
        clone.angleLabelsVisible = this.angleLabelsVisible;
        clone.angleLabelFont = this.angleLabelFont;
        clone.angleLabelPaint = this.angleLabelPaint;
        clone.angleGridlinesVisible = this.angleGridlinesVisible;
        clone.angleGridlineStroke = this.angleGridlineStroke;
        clone.angleGridlinePaint = this.angleGridlinePaint;
        clone.radiusGridlinesVisible = this.radiusGridlinesVisible;
        clone.radiusGridlineStroke = this.radiusGridlineStroke;
        clone.radiusGridlinePaint = this.radiusGridlinePaint;
        clone.radiusMinorGridlinesVisible = this.radiusMinorGridlinesVisible;
        clone.margin = this.margin;
        clone.cornerTextItems = new ArrayList(this.cornerTextItems);
        clone.fixedLegendItems = this.fixedLegendItems;

        // Clone axes
        clone.axes = (ObjectList) ObjectUtilities.clone(this.axes);
        for (int i = 0; i < this.axes.size(); i++) {
            ValueAxis axis = (ValueAxis) this.axes.get(i);
            if (axis != null) {
                ValueAxis clonedAxis = (ValueAxis) axis.clone();
                clone.axes.set(i, clonedAxis);
                clonedAxis.setPlot(clone);
                clonedAxis.addChangeListener(clone);
            }
        }

        // Clone datasets (not the data, just the references, but add listeners)
        clone.datasets = (ObjectList) ObjectUtilities.clone(this.datasets);
        for (int i = 0; i < clone.datasets.size(); ++i) {
            XYDataset d = getDataset(i);
            if (d != null) {
                d.addChangeListener(clone);
            }
        }

        // Clone renderers
        clone.renderers = (ObjectList) ObjectUtilities.clone(this.renderers);
        for (int i = 0; i < this.renderers.size(); i++) {
            PolarItemRenderer renderer2 = (PolarItemRenderer) this.renderers.get(i);
            if (renderer2 instanceof PublicCloneable) {
                PublicCloneable pc = (PublicCloneable) renderer2;
                PolarItemRenderer rc = (PolarItemRenderer) pc.clone();
                clone.renderers.set(i, rc);
                rc.setPlot(clone);
                rc.addChangeListener(clone);
            }
        }

        // Copy axis locations
        clone.axisLocations = (ObjectList) ObjectUtilities.clone(this.axisLocations);

        // Copy dataset-to-axis mapping
        clone.datasetToAxesMap = new TreeMap(this.datasetToAxesMap);
    }

